# Walks a human through docs/runbooks/production-cutover.md (issue #84).
#
# Run it on the homelab host from the deploy runner's checkout of main, so
# `docker compose --profile prod` sees the running containers. Every file it
# keeps (env, log, OPML, dump) lives in CUTOVER_DIR, outside the checkout: the
# deploy's actions/checkout cleans untracked files on every run.

# ── helpers local to this wizard ──────────────────────────────────────────
AGREGADO_DIR="${AGREGADO_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
HOMELAB_APPS_DIR="${HOMELAB_APPS_DIR:-$AGREGADO_DIR/../homelab-apps}"
CUTOVER_DIR="${CUTOVER_DIR:-$HOME/agregado-cutover}"
BACKUPS="$CUTOVER_DIR/backups"
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE="$CUTOVER_DIR/cutover.env"
CUTOVER_LOG="${CUTOVER_LOG:-$CUTOVER_DIR/cutover-$(date -u +%Y%m%dT%H%M%SZ).log}"
DB_CONTAINER="${DB_CONTAINER:-agregado-db}"
cd "$AGREGADO_DIR"
(umask 077 && mkdir -p "$CUTOVER_DIR" "$BACKUPS")

# log "text" appends a timestamped line to the cutover log.
log() { printf '%s %s\n' "$(date -u +%FT%TZ)" "$*" >> "$CUTOVER_LOG"; }

# _on_fail LABEL RC lets the human decide what to do instead of aborting.
_on_fail() {
  warn "exit status $2"; log "FAIL($2) $1"
  confirm "That failed. Continue anyway? (n aborts the wizard)" || { say "Stopped. Log: $CUTOVER_LOG"; exit 1; }
}

# run CMD... shows and logs the command and streams its output into the log.
run() {
  say "\$ $*"; log "RUN $*"
  local rc=0
  "$@" 2>&1 | tee -a "$CUTOVER_LOG" || rc=${PIPESTATUS[0]}
  (( rc == 0 )) || _on_fail "$*" "$rc"
}

# run_redacted "label" CMD... is run for commands whose arguments hold a
# secret: only the label is shown and logged.
run_redacted() {
  local label="$1"; shift
  say "\$ $label"; log "RUN $label"
  local rc=0
  "$@" 2>&1 | tee -a "$CUTOVER_LOG" || rc=${PIPESTATUS[0]}
  (( rc == 0 )) || _on_fail "$label" "$rc"
}

# gate "text" requires an explicit yes, or stops the wizard.
gate() { confirm "$1" || { log "ABORT at: $1"; say "Stopped. Re-run later; log: $CUTOVER_LOG"; exit 1; }; log "OK $1"; }

# load_env exports everything saved so far, for the Go commands and the dump.
load_env() { set -a; source "$ENV_FILE"; set +a; }

# private_api METHOD PATH calls Agregado's secret-protected n8n API.
private_api() {
  curl -fsS -X "$1" -H "X-Enrichment-Secret: $ENRICHMENT_SECRET" "$AGREGADO_BASE_URL$2"
}

# sql "query" runs a query against the live database, unaligned output.
sql() { docker exec -i "$DB_CONTAINER" psql -v ON_ERROR_STOP=1 -U "$DATABASE_USER" -d "${2:-$DATABASE_DB}" -At -F',' -c "$1"; }

run_wizard() {

TOTAL_STAGES=15

banner "Agregado production cutover (#84)"
say "Log: $CUTOVER_LOG"
say "State: $CUTOVER_DIR (outside the checkout, on purpose)"
say "Runbook: docs/runbooks/production-cutover.md"
say "One-way stages are marked [one-way] and ask for an explicit yes."
log "START commit=$(git rev-parse HEAD 2>/dev/null || echo unknown)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Go / no-go"
say "Every line must be true. Anything 'n' stops the wizard."
gate "#78, #79, #80, #81, #82, #83 are closed, and this wizard's commit is deployed from main?"
gate "Tailscale Serve exposes Agregado on the tailnet, and this device is on it (ADR-0008)?"
gate "It is after today's 08:00 Berlin, and you will finish before 01:00 Berlin?"
note "(The Digest is keyed by UTC date. Outside that window, the 08:00 schedule"
note " would send the artifact this cutover creates a second time.)"
gate "You know where off-box backup copies go?"
say "The deploy's containers must be visible from here:"
run docker compose --profile prod ps --status running agregado
say "Running both test suites on the deploy commit…"
run go test ./...
run bash -c 'cd n8n && npm test'

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Final Karakeep backup (AC 1)"
say "Forces one run of the verified backup sidecar in $HOMELAB_APPS_DIR."
gate "Run the Karakeep backup now?"
run bash -c "cd '$HOMELAB_APPS_DIR' && docker compose run --rm -e BACKUP_ONCE=1 karakeep-backup"
say "The run must report verified assets and an upload. Read the output above."
gate "Backup succeeded and uploaded?"
note "Optional but recommended: confirm the archive in R2 and rehearse a restore (homelab-apps/docs/karakeep-backup.md)."
pause "Press Enter when done"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "OPML export of current Sources"
ask OLD_AGREGADO_URL "Old Agregado base URL (e.g. http://localhost:8080):"
write_env OLD_AGREGADO_URL "$OLD_AGREGADO_URL"
OPML="$BACKUPS/sources-$(date -u +%F).opml"
run curl -fsS "$OLD_AGREGADO_URL/api/sources/export" -o "$OPML"
[[ -s "$OPML" ]] || { warn "OPML is empty or missing"; exit 1; }
say "Saved $OPML ($(wc -c < "$OPML") bytes, $(grep -c '<outline' "$OPML" || true) outlines)"
log "OPML $OPML sha256=$(sha256sum "$OPML" | cut -d' ' -f1)"
pause "Copy it off-box now, then press Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Migration prerequisites"
ask BASE_DOMAIN "Your base domain (e.g. example.com):"
write_env BASE_DOMAIN "$BASE_DOMAIN"
open_url "https://karakeep.$BASE_DOMAIN/settings/api-keys"
step "In Karakeep: Settings → API Keys → create one named 'agregado-migration'."
ask KARAKEEP_ADDRESS "Karakeep origin, no /api/v1 (e.g. https://karakeep.$BASE_DOMAIN):"
ask_secret KARAKEEP_API_KEY "Paste the API key:"
write_env KARAKEEP_ADDRESS "$KARAKEEP_ADDRESS"
write_env KARAKEEP_API_KEY "$KARAKEEP_API_KEY"
say "The migration loads the full Agregado config, so it needs the deploy's values."
ask DATABASE_USER "DATABASE_USER:"
ask_secret DATABASE_PASSWORD "DATABASE_PASSWORD:"
ask DATABASE_DB "DATABASE_DB:"
ask_secret ENRICHMENT_SECRET "ENRICHMENT_SECRET (same value as the deploy secret):"
write_env DATABASE_USER "$DATABASE_USER"
write_env DATABASE_PASSWORD "$DATABASE_PASSWORD"
write_env DATABASE_DB "$DATABASE_DB"
write_env DATABASE_HOST localhost
write_env ENRICHMENT_SECRET "$ENRICHMENT_SECRET"
# Required by config.Load, never used by the migration.
write_env RABBITMQ_USER unused
write_env RABBITMQ_PASS unused
# Same shape as deploy.yml's "Build POSTGRESQL_URL" step.
write_env POSTGRESQL_URL "postgres://${DATABASE_USER}:${DATABASE_PASSWORD}@localhost:5432/${DATABASE_DB}?sslmode=disable"
run_redacted "migrate -database <POSTGRESQL_URL> -path migrations up" \
  migrate -database "$POSTGRESQL_URL" -path migrations up

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Migration dry run"
load_env
run go run ./cmd/migrate-ownership
say "Check: FAIL is 0; source_config and article_bodies show DEST 0;"
say "SKIP is roughly your newsletter volume; samples read DIFF 'absent' (nothing written)."
gate "Dry run looks right?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Apply the migration [one-way into Karakeep / Article Index] (AC 2)"
warn "Writes Bookmarks into Karakeep and rows into the Article Index."
gate "Apply now?"
run go run ./cmd/migrate-ownership -apply
say "Samples should be OK (except legitimately preserved live rows). FAIL must be 0."
gate "First apply is clean?"
say "Second apply is the idempotency check: every class DEST 0."
run go run ./cmd/migrate-ownership -apply
gate "Second apply shows DEST 0 everywhere and totals reconcile (SOURCE = DEST + SKIP + DUP)?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Final cold dump [briefly stops the agregado container] (AC 1)"
warn "The script stops agregado for the dump and restarts it on exit."
gate "Take the cold dump now?"
run scripts/legacy-postgres-dump.sh "$BACKUPS"
MANIFEST=$(ls -t "$BACKUPS"/agregado-legacy-*.manifest.txt | head -1)
grep -qE '^restore: +VERIFIED' "$MANIFEST" || { warn "$MANIFEST does not say restore: VERIFIED"; exit 1; }
say "Manifest $MANIFEST says restore: VERIFIED."
write_env MANIFEST "$MANIFEST"
log "DUMP manifest=$MANIFEST"
run sha256sum -c <<< "$(grep sha256 "$MANIFEST" | awk '{print $2}')  ${MANIFEST/.manifest.txt/.dump}"
pause "Copy the .dump and manifest OFF-BOX now (keep forever), then press Enter"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Deploy: legacy RSS poller off, Digest links on the tailnet"
say "Miniflux takes over the Sources next. The in-process poller must be off first,"
say "or every Article is ingested and enriched (and paid for) twice."
ask AGREGADO_BASE_URL "Agregado's Tailscale Serve URL (e.g. https://agregado.<tailnet>.ts.net):"
write_env AGREGADO_BASE_URL "$AGREGADO_BASE_URL"
set_var RSS_POLLER_ENABLED false
say "Digest Open and vote links are tailnet-only (ADR-0008):"
set_secret PUBLIC_BASE_URL "$AGREGADO_BASE_URL"
step "Re-run the latest 'Deploy to local server' run: gh run rerun <id>"
note "(deploy.yml has no workflow_dispatch; a re-run reads the current vars and secrets.)"
pause "Press Enter when the deploy run is green"
say "The log line proves the re-run picked up the new variable, which is also the rollback path:"
run bash -c "docker compose --profile prod logs agregado 2>&1 | grep -m1 'legacy RSS poller disabled'"
run curl -fsS "$AGREGADO_BASE_URL/health"
run curl -fsS "$AGREGADO_BASE_URL/health/db"
gate "Log line present and both health checks returned ok?"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "n8n: import workflows"
open_url "https://n8n.$BASE_DOMAIN"
say "Import from n8n/workflows/: article-enrichment, newsletter-ingest, daily-digest, preferences-sync."
note "CLI: n8n import:workflow --input=<file> (inside the n8n container), or paste into the editor."
say "Set env + credentials per n8n/README.md → 'Configuration (n8n)':"
step "Resend, Cloudflare D1/R2, RESEND_WEBHOOK_SECRET, BRIDGE_PERMALINK_SECRET (never rotate)"
step "MINIFLUX_WEBHOOK_SECRET, BRIDGE_ORIGIN, AGREGADO_BASE_URL=$AGREGADO_BASE_URL, ENRICHMENT_SECRET"
step "SMTP credential, DIGEST_RECIPIENT_EMAIL, DIGEST_FROM_EMAIL"
step "Google Drive OAuth2 (full scope, app 'In production'), PREFERENCES_DOC_ID"
say "Enrichment refuses to run until a preference profile is stored (ADR-0010)."
if private_api GET /api/private/preferences >/dev/null 2>&1; then
  say "A preference profile is stored."
else
  step "No profile yet: in n8n, run preferences-sync once by hand (Execute workflow)."
  pause "Press Enter when it succeeded"
  run_redacted "GET /api/private/preferences" private_api GET /api/private/preferences
fi
warn "Activate ONLY the webhook workflows now. Leave daily-digest and preferences-sync schedules OFF."
pause "Press Enter when imported and the webhook workflows are active"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Miniflux: subscriptions and webhook"
open_url "https://miniflux.$BASE_DOMAIN/import"
step "Import $OPML (Settings → Import)."
open_url "https://miniflux.$BASE_DOMAIN/integrations"
step "Integrations → Webhook: URL = the n8n article-enrichment webhook (with its random suffix)."
step "Set the webhook secret to your MINIFLUX_WEBHOOK_SECRET."
step "Check entry retention isn't pruning Articles you want."
warn "The first fetch of every Source sends its current entries to enrichment: expect a model-cost burst."
pause "Press Enter when Miniflux is configured"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Newsletter Sources onto the Bridge"
say "Follow docs/runbooks/newsletter-source-onboarding.md for each newsletter Source:"
step "D1 source row → subscribe at the publisher → status 'active' → subscribe in Miniflux to the Bridge feed."
note "Resend's webhook reaches n8n through the ingest hostname; that route stays (ADR-0007)."
note "The old Agregado tunnel routes stay up until stage 15, so the cutover fails closed (ADR-0008)."
pause "Press Enter when done"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Verify live ingestion (AC 3)"
step "RSS: force a refresh of a fast Source in Miniflux. Confirm the entry, a successful article-enrichment execution, and an article_index row with Score/tags/summary."
step "Email-only Article (a newsletter with no canonical URL): confirm Bridge → Miniflux → enrichment → article_index keyed by the permalink UUID."
say "Newest Article Index rows:"
