# ── 13 ────────────────────────────────────────────────────────────────────
stage "Verify Open and feedback (AC 4)"
warn "These are real preference signals: pick an Article you would open and upvote anyway."
ask ARTICLE_ID "Its Article Index id (from the list above):"
say "Open twice; both must redirect (302), the first Open must not move:"
run curl -s -o /dev/null -w '%{http_code} -> %{redirect_url}\n' "$AGREGADO_BASE_URL/r/$ARTICLE_ID"
FIRST_OPEN=$(sql "SELECT opened_at FROM article_index WHERE id = '$ARTICLE_ID'")
run curl -s -o /dev/null -w '%{http_code} -> %{redirect_url}\n' "$AGREGADO_BASE_URL/r/$ARTICLE_ID"
SECOND_OPEN=$(sql "SELECT opened_at FROM article_index WHERE id = '$ARTICLE_ID'")
say "opened_at: $FIRST_OPEN, then $SECOND_OPEN"
[[ -n "$FIRST_OPEN" && "$FIRST_OPEN" == "$SECOND_OPEN" ]] || warn "Expected one Open, recorded once"
gate "Both 302 and exactly one Open recorded?"
say "Feedback: down then up replaces the vote; any other vote is 404:"
run curl -fsS -o /dev/null "$AGREGADO_BASE_URL/f/$ARTICLE_ID/down"
FIRST_VOTE=$(sql "SELECT created_at FROM article_index_feedback WHERE article_index_id = '$ARTICLE_ID'")
run curl -fsS -o /dev/null "$AGREGADO_BASE_URL/f/$ARTICLE_ID/up"
run curl -s -o /dev/null -w '%{http_code}\n' "$AGREGADO_BASE_URL/f/$ARTICLE_ID/sideways"
run sql "SELECT vote, created_at, updated_at FROM article_index_feedback WHERE article_index_id = '$ARTICLE_ID'"
say "created_at after the first vote: $FIRST_VOTE"
gate "One row, vote 'up', created_at unchanged, sideways was 404?"

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Digest retry and preferences (AC 5-6)"
D=$(date -u +%F)
say "Fetching the persisted Digest for $D twice; bodies must be identical."
A=$(private_api POST "/api/private/digests/$D" | sha256sum | cut -d' ' -f1)
B=$(private_api POST "/api/private/digests/$D" | sha256sum | cut -d' ' -f1)
