step "In n8n, run daily-digest manually; confirm the email arrives and its links start with $AGREGADO_BASE_URL."
open_url "https://${LANGFUSE_HOST:-langfuse.$BASE_DOMAIN}"
step "Langfuse: one digest_select trace for $D at most, none after the second fetch or the n8n send."
gate "No extra model call for the retry?"
step "In n8n, run preferences-sync manually."
warn "AC 6 asks for a reviewable proposal; ADR-0010 removed that gate: the workflow writes the Doc directly."
gate "Accept the alert diff + Doc revision history as the review? (n: stop and open a follow-up issue)"
step "Edit the Doc into a malformed state, run again, expect a 400 alert, then revert."
pause "Press Enter when done"
step "Now ACTIVATE the Schedule triggers on daily-digest and preferences-sync."
pause "Press Enter when both are active"

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Rollback drill, then stop the old public routes (AC 7)"
warn "Stop, do NOT remove containers/images/volumes. Do NOT drop old tables (#85)."
say "Rollback path (runbook → Rollback): deactivate the n8n workflows and the Miniflux"
say "webhook, set RSS_POLLER_ENABLED=true, re-run the deploy. Stage 8 already proved"
say "a re-run applies a changed variable. What is left to drill is the dump:"
ask OFFBOX_DUMP "Path to the dump copied BACK from off-box (not the local one):"
DRILL=agregado_rollback_drill
run sql "DROP DATABASE IF EXISTS $DRILL" postgres
run sql "CREATE DATABASE $DRILL" postgres
run bash -c "docker exec -i '$DB_CONTAINER' pg_restore -U '$DATABASE_USER' -d '$DRILL' --no-owner --no-acl < '$OFFBOX_DUMP'"
say "Row counts, restored vs. manifest:"
MISMATCH=0
while IFS=, read -r table want; do
  got=$(sql "SELECT COUNT(*) FROM $table" "$DRILL")
  printf '  %-24s manifest %-8s restored %s\n' "$table" "$want" "$got"
  [[ "$got" == "$want" ]] || MISMATCH=1
done < <(sed -n '/^row counts at dump time:/,$p' "$MANIFEST" | tail -n +2 | sed 's/^ *//' | grep ,)
run sql "DROP DATABASE $DRILL" postgres
(( MISMATCH == 0 )) || warn "Counts differ: the off-box copy does not match the manifest"
step "Confirm the PREFERENCES Doc has a revision to roll back to."
gate "Off-box dump restored with matching counts, and a Doc revision exists?"
say "Old newsletter ingress: any hit on /webhook/email means a publisher still mails"
say "an old address. Onboard it onto the Bridge before its route goes."
run bash -c "docker compose --profile prod logs --since 24h agregado 2>&1 | grep -c '/webhook/email' || true"
gate "No unexplained /webhook/email traffic?"
say "Rollback is exercised, so the old public routes go now (ADR-0008 #2, #6):"
step "Cloudflare Zero Trust → Tunnels: remove the read hostname and every route whose origin is Agregado."
step "Keep the ingest hostname's /webhook/resend-<suffix> route to n8n and its rate limit."
ask OLD_PUBLIC_URL "The old public read URL (e.g. https://read.$BASE_DOMAIN):"
say "From outside the tailnet it must no longer reach Agregado:"
run curl -s -o /dev/null -w '%{http_code}\n' --max-time 10 "$OLD_PUBLIC_URL/health"
gate "Public routes removed (non-200 above) and Agregado still answers on the tailnet?"
log "DONE cutover wizard"

say "Cutover log: $CUTOVER_LOG"
say "Next: comment the log summary on #84 (and update AC 6 to match ADR-0010),"
say "close it, and start #85 after the ~48h observation window."

finish
}

run_wizard "$@"; exit
